iscperc=saledetail.claimablediscperc, balancestock=saledetail.balancestock, godownbalancestock=saledetail.godownbalancestock, taxflag = 1, unitsalestax=saledetail.unitsalestax, PackSalePrice = saledetail.PackSalePrice, totalpieces = saledetail.totalpieces, piecesinhand = saledetail.piecesinhand, commissionperunit=saledetail.commissionperunit, commissionperc=saledetail.commissionperc, gstperc=saledetail.gstperc, YourLotNo = saledetail.YourLotNo, YourExpiry = saledetail.YourExpiry, YourPacking = saledetail.YourPacking, SaleTypeCode=1, SaleCatCode=1, taxable = 'N', ItemAdvanceTaxPerc = saledetail.ItemAdvanceTaxPerc, bonusqty=saledetail.bonusqty FROM saledetail WHERE ( dbo.saledetail.saleinvcode = 359939 ) ORDER BY saledetail.IDENTITYCOL;
